// Fill spots freed by cancellations from the waitlist.
// Founding-tier members go first; anyone who declined twice is dropped.
export function promoteFromWaitlist(cls, cancelled) {
  const gone = new Set(cancelled);
  const booked = cls.booked.filter((name) => !gone.has(name));
  const eligible = cls.waitlist.filter((w) => w.declines < 2);
  const queue = [
    ...eligible.filter((w) => w.tier === "founding"),
    ...eligible.filter((w) => w.tier !== "founding"),
  ];
  const open = Math.max(0, cls.capacity - booked.length);
  const promoted = queue.slice(0, open);
  return {
    booked: [...booked, ...promoted.map((w) => w.name)],
    waitlist: queue.slice(open),
  };
}
EOF
