import { overlaps } from "./shifts.js";

// Hours of rest a worker needs between the end of one shift and the start of the next.
export const MIN_REST_HOURS = 11;

// Whether the worker can take the shift, given their other shifts in the schedule.
export function canSwap(worker, shift, schedule) {
  if (worker.trainee && shift.night) return false;
  return schedule.every(
    (other) =>
      !overlaps(shift, other) &&
      (shift.start - other.end >= MIN_REST_HOURS || other.start - shift.end >= MIN_REST_HOURS)
  );
}
