const FREE_DOMESTIC_SEGMENTS = 100;
const DOMESTIC_CENTS = 2;
const INTERNATIONAL_CENTS = 5;

// One month's bill in cents. The first 100 domestic segments are free;
// international segments are always charged and never use up the free ones.
export function monthlyBill(messages) {
  let domestic = 0;
  let international = 0;
  for (const { segments, international: isInternational } of messages) {
    if (isInternational) international += segments;
    else domestic += segments;
  }
  const billableDomestic = Math.max(0, domestic - FREE_DOMESTIC_SEGMENTS);
  return billableDomestic * DOMESTIC_CENTS + international * INTERNATIONAL_CENTS;
}
