import { daysOverdue } from "./loans.js";

const FINE_PER_DAY_CENTS = 25;

// Fine in cents for a loan: 25 cents per day overdue, capped at the item's
// replacement cost. Children's cards are never fined.
export function fineFor({ dueDate, returnedDate, replacementCents, card }) {
  if (card === "child") return 0;
  const fine = daysOverdue(dueDate, returnedDate) * FINE_PER_DAY_CENTS;
  return Math.min(fine, replacementCents);
}
