const ECONOMY_KG_PER_KM = 0.15;
const CABIN_FACTOR = { economy: 1, business: 2.9 };
const SHORT_FLIGHT_KM = 500;
const SHORT_FLIGHT_EXTRA_KG = 50;

// Kilograms of CO2 for a flight, rounded to whole kilograms.
